# Approvals page, the reporting officer (13 Nov 2026):
#   1. Server Script "Field Trip Officer API" (API, method field_trip_officer):
#      the officer changes a TA (Travel) line's amount with a reason while the
#      claim waits with them -- only DOWN, never above the amount claimed
#      (13 Nov 2026); and reads each claim day's visits per town.
#   2. Server Script "Field Trip Decision Guard" (Expense Claim, Before Save):
#      also keeps the officer's TA change on a line the employee did not change.
#      Replaced only if the live script is the one this was written against.
#
# Paste into ERP > System Console (Python). DRY = True first (only prints);
# then DRY = False and tick Commit. Safe to re-run.

DRY = True
W = "WOULD " if DRY else ""
LF = chr(10)
CR = chr(13)

OFFICER_API = '# Server Script "Field Trip Officer API" -- type API, method field_trip_officer (13 Nov 2026).\n# What the reporting officer needs on the approvals page besides the trip\n# decision ("Field Trip Decision API"), for a rep\'s monthly field TA/DA claim\n# (remark "Field TA/DA · YYYY-MM"):\n#\n#   POST action=adjust  claim, lines (JSON [{row, amount}]), reason\n#        The officer changes the amount of a TA (Travel) line while the claim\n#        waits with them -- with a reason, which the employee sees. Only DOWN:\n#        never above the amount claimed (13 Nov 2026). Stored the\n#        same way as the final check\'s adjustments (custom_adjusted /\n#        _adjusted_amount / _adjust_reason / _adjusted_by / _adjusted_on, and\n#        sanctioned_amount): the planner, the dashboard and payroll all read\n#        the adjusted amount. The amount set back to the claimed one clears it.\n#        "Field Trip Decision Guard" keeps an adjustment on a line the rep did\n#        not change when they save again.\n#        -> {claim, changed}\n#\n#   GET  action=visits  claim\n#        The visits behind each day of the claim, from the rep\'s Field Expense\n#        Day (the officer has no permission on that DocType): per date, how\n#        many and in which towns.\n#        -> {claim, days: {date: {visits, places: {town: n}}}}\n#\n# Who: the claim\'s own approver (expense_approver) or a System Manager.\n# safe_exec: plain loops only, no defs, no comprehensions over top-level names.\n\nPREFIX = "Field TA/DA · "\nTA_TYPES = ["Travel"]\nfd = frappe.form_dict\naction = str(fd.get("action") or "")\nme = frappe.session.user\nif not me or me == "Guest":\n    frappe.throw("Please log in", frappe.PermissionError)\n\nname = str(fd.get("claim") or "")\nc = frappe.db.get_value("Expense Claim", name, ["name", "employee", "remark", "workflow_state", "expense_approver", "docstatus"], as_dict=True) if name else None\nif not c or not str(c.remark or "").startswith(PREFIX):\n    frappe.throw("Not a planner field claim.")\nadmin = me == "Administrator" or frappe.db.exists("Has Role", {"parent": me, "parenttype": "User", "role": "System Manager"})\nif c.expense_approver != me and not admin:\n    frappe.throw("Only " + str(c.expense_approver or "the reporting officer") + " can see or change this claim here.", frappe.PermissionError)\n\nif action == "adjust":\n    if int(c.docstatus or 0) != 0 or c.workflow_state != "Waiting for Approval":\n        frappe.throw("This claim is " + str(c.workflow_state or "not waiting") + " -- its TA can be changed only while it waits for approval.")\n    reason = " ".join(str(fd.get("reason") or "").split())[:1000]\n    wanted = json.loads(fd.get("lines") or "[]")\n    if not wanted:\n        frappe.throw("Which line?")\n    now = frappe.utils.now()\n    text = []\n    for w in wanted:\n        rn = str(w.get("row") or "")\n        r = frappe.db.get_value("Expense Claim Detail", rn, ["name", "parent", "expense_type", "expense_date", "amount", "custom_adjusted", "custom_adjusted_amount"], as_dict=True) if rn else None\n        if not r or r.parent != name:\n            frappe.throw("A line of " + name + " was not found -- refresh and try again.")\n        if r.expense_type not in TA_TYPES:\n            frappe.throw("Only a TA (Travel) line can be changed here.")\n        amt = frappe.utils.flt(w.get("amount"))\n        if amt < 0:\n            frappe.throw("An amount cannot be below 0.")\n        if amt > frappe.utils.flt(r.amount) + 0.5:\n            frappe.throw("The TA can only be reduced -- at most Rs " + str(frappe.utils.flt(r.amount)) + ", the amount claimed.")\n        was = frappe.utils.flt(r.custom_adjusted_amount) if r.custom_adjusted else frappe.utils.flt(r.amount)\n        if abs(amt - was) < 0.5:\n            continue\n        if abs(amt - frappe.utils.flt(r.amount)) < 0.5:\n            frappe.db.set_value("Expense Claim Detail", r.name, {"custom_adjusted": 0, "custom_adjusted_amount": 0, "custom_adjust_reason": "", "custom_adjusted_by": None, "custom_adjusted_on": None, "sanctioned_amount": r.amount}, update_modified=False)\n        else:\n            if len(reason) < 3:\n                frappe.throw("Say why the TA is changed -- the employee sees this.")\n            frappe.db.set_value("Expense Claim Detail", r.name, {"custom_adjusted": 1, "custom_adjusted_amount": amt, "custom_adjust_reason": reason, "custom_adjusted_by": me, "custom_adjusted_on": now, "sanctioned_amount": amt}, update_modified=False)\n        text.append("TA " + str(r.expense_date) + ": Rs " + str(was) + " -> Rs " + str(amt))\n    if text:\n        frappe.get_doc({\n            "doctype": "Comment",\n            "comment_type": "Comment",\n            "reference_doctype": "Expense Claim",\n            "reference_name": name,\n            "comment_email": me,\n            "content": "TA changed by the reporting officer: " + "; ".join(text) + ((". Reason: " + reason) if reason else ""),\n        }).insert(ignore_permissions=True)\n    frappe.response["message"] = {"claim": name, "changed": len(text)}\n\nelif action == "visits":\n    dates = []\n    for l in frappe.get_all("Expense Claim Detail", filters={"parent": name, "parenttype": "Expense Claim"}, fields=["expense_date"], limit_page_length=1000):\n        d = str(l.expense_date)[:10]\n        if d and d not in dates:\n            dates.append(d)\n    out = {}\n    if dates and c.employee:\n        for d in frappe.get_all("Field Expense Day", filters={"employee": c.employee, "date": ["in", dates]}, fields=["date", "visits", "detail_json"], limit_page_length=0):\n            places = {}\n            det = {}\n            if d.detail_json:\n                det = json.loads(d.detail_json) or {}\n            for v in det.get("visitList") or []:\n                p = ""\n                if v and len(v) > 2:\n                    p = " ".join(str(v[2] or "").split())\n                if p:\n                    places[p] = places.get(p, 0) + 1\n            out[str(d.date)[:10]] = {"visits": d.visits or 0, "places": places}\n    frappe.response["message"] = {"claim": name, "days": out}\n\nelse:\n    frappe.throw("Unknown action.")\n'

GUARD_OLD = '# Server Script "Field Trip Decision Guard" -- DocType Event, Expense Claim,\n# Before Save (12 Nov 2026).\n#\n# The officer\'s per-trip decision (custom_trip_decision / _note / _decided_by /\n# _decided_on on each line) is written only by the "Field Trip Decision API".\n# Any save of a planner field claim -- the rep adding a trip, the workflow\n# moving -- takes those fields from the database, never from what was sent:\n#   a line that is unchanged (same date, type, amount and bill) keeps its\n#   decision; a changed or new line starts undecided.\n# So after a send-back the trips already approved stay approved, and the one\n# the rep fixed comes back to the officer. The line\'s trip tag (custom_trip)\n# is kept the same way when a save leaves it out.\n\nPREFIX = "Field TA/DA · "\nKEEP = ["custom_trip_decision", "custom_trip_note", "custom_trip_decided_by", "custom_trip_decided_on"]\n\nif str(doc.remark or "").startswith(PREFIX):\n    old = {}\n    if not doc.is_new():\n        for r in frappe.get_all(\n            "Expense Claim Detail",\n            filters={"parent": doc.name, "parenttype": "Expense Claim"},\n            fields=["name", "expense_date", "expense_type", "amount", "custom_bill", "custom_trip", "custom_trip_decision", "custom_trip_note", "custom_trip_decided_by", "custom_trip_decided_on"],\n            limit_page_length=1000,\n        ):\n            old[r.name] = r\n    for row in doc.expenses:\n        o = old.get(row.name) if row.name else None\n        same = False\n        if o:\n            same = (\n                str(o.expense_date)[:10] == str(row.expense_date or "")[:10]\n                and (o.expense_type or "") == (row.expense_type or "")\n                and abs(frappe.utils.flt(o.amount) - frappe.utils.flt(row.amount)) < 0.01\n                and (o.custom_bill or "") == (row.custom_bill or "")\n            )\n        for k in KEEP:\n            row.set(k, o.get(k) if same else None)\n        if o and not row.get("custom_trip") and o.get("custom_trip"):\n            row.set("custom_trip", o.get("custom_trip"))\n'

GUARD_NEW = '# Server Script "Field Trip Decision Guard" -- DocType Event, Expense Claim,\n# Before Save (12 Nov 2026).\n#\n# The officer\'s per-trip decision (custom_trip_decision / _note / _decided_by /\n# _decided_on on each line) is written only by the "Field Trip Decision API".\n# Any save of a planner field claim -- the rep adding a trip, the workflow\n# moving -- takes those fields from the database, never from what was sent:\n#   a line that is unchanged (same date, type, amount and bill) keeps its\n#   decision; a changed or new line starts undecided.\n# So after a send-back the trips already approved stay approved, and the one\n# the rep fixed comes back to the officer. The line\'s trip tag (custom_trip)\n# is kept the same way when a save leaves it out.\n# 13 Nov 2026: so is a TA amount the officer changed ("Field Trip Officer\n# API": custom_adjusted / _adjusted_amount / _adjust_reason / _adjusted_by /\n# _adjusted_on and sanctioned_amount) -- kept on an unchanged line, cleared on\n# a changed one.\n\nPREFIX = "Field TA/DA · "\nKEEP = ["custom_trip_decision", "custom_trip_note", "custom_trip_decided_by", "custom_trip_decided_on"]\nADJ = ["custom_adjusted", "custom_adjusted_amount", "custom_adjust_reason", "custom_adjusted_by", "custom_adjusted_on"]\n\nif str(doc.remark or "").startswith(PREFIX):\n    old = {}\n    if not doc.is_new():\n        for r in frappe.get_all(\n            "Expense Claim Detail",\n            filters={"parent": doc.name, "parenttype": "Expense Claim"},\n            fields=["name", "expense_date", "expense_type", "amount", "sanctioned_amount", "custom_bill", "custom_trip", "custom_trip_decision", "custom_trip_note", "custom_trip_decided_by", "custom_trip_decided_on",\n                    "custom_adjusted", "custom_adjusted_amount", "custom_adjust_reason", "custom_adjusted_by", "custom_adjusted_on"],\n            limit_page_length=1000,\n        ):\n            old[r.name] = r\n    for row in doc.expenses:\n        o = old.get(row.name) if row.name else None\n        same = False\n        if o:\n            same = (\n                str(o.expense_date)[:10] == str(row.expense_date or "")[:10]\n                and (o.expense_type or "") == (row.expense_type or "")\n                and abs(frappe.utils.flt(o.amount) - frappe.utils.flt(row.amount)) < 0.01\n                and (o.custom_bill or "") == (row.custom_bill or "")\n            )\n        for k in KEEP:\n            row.set(k, o.get(k) if same else None)\n        if same and o.get("custom_adjusted"):\n            for k in ADJ:\n                row.set(k, o.get(k))\n            row.set("sanctioned_amount", o.get("sanctioned_amount"))\n        elif row.get("custom_adjusted"):\n            for k in ADJ:\n                row.set(k, 0 if k in ["custom_adjusted", "custom_adjusted_amount"] else None)\n            row.set("sanctioned_amount", row.amount)\n        if o and not row.get("custom_trip") and o.get("custom_trip"):\n            row.set("custom_trip", o.get("custom_trip"))\n'

def_api = frappe.db.exists("Server Script", "Field Trip Officer API")
if def_api:
    ss = frappe.get_doc("Server Script", "Field Trip Officer API")
    if ss.script.replace(CR + LF, LF) == OFFICER_API:
        print("ok: Server Script Field Trip Officer API is current")
    else:
        print(W + "update Server Script Field Trip Officer API")
        if not DRY:
            ss.script = OFFICER_API
            ss.save()
else:
    print(W + "create Server Script Field Trip Officer API (method field_trip_officer)")
    if not DRY:
        frappe.get_doc({"doctype": "Server Script", "name": "Field Trip Officer API", "script_type": "API", "api_method": "field_trip_officer",
                        "allow_guest": 0, "disabled": 0, "script": OFFICER_API}).insert(ignore_permissions=True)

g = frappe.get_doc("Server Script", "Field Trip Decision Guard")
live = g.script.replace(CR + LF, LF)
if live == GUARD_NEW:
    print("ok: Server Script Field Trip Decision Guard is current")
elif live == GUARD_OLD:
    print(W + "update Server Script Field Trip Decision Guard (keeps the officer's TA change)")
    if not DRY:
        g.script = GUARD_NEW
        g.save()
else:
    print("STOP: Field Trip Decision Guard was changed in the ERP since -- not replaced. Send its current script to update it.")

if not DRY:
    frappe.db.commit()
print("DRY RUN: nothing changed. Set DRY = False, tick Commit, run again." if DRY else "done")
